function readCancelRequest(paths: ManagedHostRunPaths): ManagedHostRunCancelRequest | null {
  return existsSync(paths.cancelRequest) ? readJson<ManagedHostRunCancelRequest>(paths.cancelRequest) : null;
}

function readTerminal(paths: ManagedHostRunPaths): ManagedHostRunTerminal | null {
  return existsSync(paths.terminal) ? readJson<ManagedHostRunTerminal>(paths.terminal) : null;
