298	  staleMs: number,
299	  lockTiming: ProviderRegistryLockTiming = {},
300	): ProviderProcessLiveDescriptor[] {
301	  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
302	}
303	
304	export function acquireProviderProcessSlot(
305	  dir: string,
306	  cap: number,
307	  staleMs: number,
308	  now: number,
309	  meta: ProviderProcessSlotMeta,
310	  lockTiming: ProviderRegistryLockTiming = {},
311	): AcquiredProviderProcessSlot | null {
312	  mkdirSync(dir, { recursive: true });
313	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
314	    ? cap
315	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
316	  return withProviderRegistryLock(dir, () => {
317	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
318	    if (live.length >= boundedCap) return null;
319	    const token = randomUUID();
320	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
321	    for (let index = 0; index < boundedCap; index += 1) {
322	      const file = join(dir, `slot-${index}.json`);
323	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
324	      const judged = readSlotOccupant(file);
325	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
326	      if (judged.state !== 'missing') {
327	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
328	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
329	      }
330	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
331	    }
332	    return null;
333	  }, lockTiming);
334	}
335	
336	export function releaseProviderProcessSlot(
337	  file: string | null,
338	  token: string | null,
339	  lockTiming: ProviderRegistryLockTiming = {},
340	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
341	): void {
342	  if (!file || !token) return;
343	  const dir = dirname(file);
344	  withProviderRegistryLock(dir, () => {
345	    const occupant = readSlotOccupant(file);
346	    if (occupant.state !== 'valid' || occupant.token !== token) return;
347	    mutationOps.unlink(file);
348	  }, lockTiming);
349	}
350	
351	export function transferProviderProcessSlotToProvider(
352	  file: string | null,
353	  token: string | null,
354	  identity: {
355	    pid: number;
356	    pgid: number | null;
357	    spawnedAt: string;
358	    startFingerprint: string | null;
359	    processGroupIsolated: boolean;
360	  },
361	  lockTiming: ProviderRegistryLockTiming = {},
362	): boolean {
363	  if (!file || !token) return false;
364	  if (
365	    !Number.isInteger(identity.pid) || identity.pid <= 0
366	    || !identity.processGroupIsolated
367	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
368	  ) return false;
369	  const dir = dirname(file);
370	  return withProviderRegistryLock(dir, () => {
371	    const occupant = readSlotOccupant(file);
372	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
373	    const next: ProviderProcessSlotFileMeta = {
374	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
375	      pid: identity.pid,
376	      providerPid: identity.pid,
377	      providerPgid: identity.pgid!,
378	      providerSpawnedAt: identity.spawnedAt,
379	      providerStartFingerprint: identity.startFingerprint ?? undefined,
380	      providerProcessGroupIsolated: true,
381	      token,
382	    };
383	    const temporary = `${file}.${token}.transfer`;
384	    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
385	    try {
386	      // Registry lock + exact token check makes this replacement ownership-safe.
387	      renameSync(temporary, file);
388	    } finally {
389	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
390	    }
391	    return true;
392	  }, lockTiming);
393	}
