{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_013CboPKko94ZqC57RsZKbRE","type":"tool_result","content":"1	/**
2	 * Ledger-independent provider-process admission.
3	 *
4	 * Usage accounting may be disabled, but every Lattice-owned provider spawn
5	 * still competes for the same atomic slot registry. This module is the small
6	 * adapter used by all Lattice-owned provider launch sites.
7	 */
8	
9	import {
10	  acquireProviderProcessSlot,
11	  providerProcessSlotsDir,
12	  releaseProviderProcessSlot,
13	  resolveProviderProcessMaxConcurrent,
14	  resolveProviderProcessSlotStaleMs,
15	  scanLiveProviderProcessSlots,
16	  transferProviderProcessSlotToProvider,
17	  type AcquiredProviderProcessSlot,
18	  type ProviderProcessLiveDescriptor,
19	} from './provider-process-registry.js';
20	
21	export interface ProviderProcessAdmissionRequest {
22	  root: string;
23	  env: NodeJS.ProcessEnv;
24	  host: string;
25	  storyId: string | null;
26	  agentType: string;
27	  startedAt?: string;
28	  pid?: number;
29	}
30	
31	export interface ProviderProcessAdmission {
32	  admitted: boolean;
33	  slot: AcquiredProviderProcessSlot | null;
34	  cap: number;
35	  liveRuns: ProviderProcessLiveDescriptor[];
36	}
37	
38	export function acquireProviderProcessAdmission(
39	  request: ProviderProcessAdmissionRequest,
40	): ProviderProcessAdmission {
41	  const dir = providerProcessSlotsDir(request.root);
42	  const cap = resolveProviderProcessMaxConcurrent(request.env);
43	  const staleMs = resolveProviderProcessSlotStaleMs(request.env);
44	  const slot = acquireProviderProcessSlot(dir, cap, staleMs, Date.now(), {
45	    pid: request.pid ?? process.pid,
46	    startedAt: request.startedAt ?? new Date().toISOString(),
47	    host: request.host,
48	    storyId: request.storyId,
49	    agentType: request.agentType,
50	  });
51	  return {
52	    admitted: slot !== null,
53	    slot,
54	    cap,
55	    liveRuns: slot ? [] : scanLiveProviderProcessSlots(dir, Date.now(), staleMs),
56	  };
57	}
58	
59	export function releaseProviderProcessAdmission(admission: ProviderProcessAdmission | null): void {
60	  if (!admission?.slot) return;
61	  releaseProviderProcessSlot(admission.slot.file, admission.slot.token);
62	}
63	
64	export function transferProviderProcessAdmissionToProvider(
65	  admission: ProviderProcessAdmission | null,
66	  identity: {
67	    pid: number;
68	    pgid: number | null;
69	    spawnedAt: string;
70	    startFingerprint: string | null;
71	    processGroupIsolated: boolean;
72	  },
73	): boolean {
74	  if (!admission?.slot) return false;
75	  return transferProviderProcessSlotToProvider(admission.slot.file, admission.slot.token, identity);
76	}
77	"}]},"parent_tool_use_id":"toolu_01SyiQwmdKhq8PadWT2MSuNC","session_id":"f15e2077-72ea-410c-8904-c79687dc9acf","uuid":"6b9952fc-dbf2-4591-9389-07d777459404","timestamp":"2026-08-18T08:45:26.121Z","subagent_type":"Explore","task_description":"Review provider process registry"}

{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_0191d7ZmHdvpqwoToN4DXGse","type":"tool_result","content":"1	import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
2	import { dirname, join } from 'node:path';
3	
4	import {
5	  signCanonical,
6	  verifyCanonical,
7	  type PrivateKeyBase64,
8	  type PublicKeyBase64,
9	  type SignatureBase64,
10	} from './authority-signing.js';
11	import { digestCanonicalJson } from './digest.js';
12	import { resolveCanonicalRuntimeProjectRoot } from './runtime-artifact-registry.js';
13	
14	export const NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA =
15	  'lattice.native_review_invocation_attestation.v1' as const;
16	
17	export interface NativeReviewBrokerRegistration {
18	  brokerId: string;
19	  adapterId: string;
20	  host: 'codex' | 'claude';
21	  publicKey: PublicKeyBase64;
22	}
23	
24	export interface NativeReviewInvocationClaims {
25	  schemaVersion: typeof NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA;
26	  brokerId: string;
27	  adapterId: string;
28	  host: 'codex' | 'claude';
29	  storyId: string;
30	  agent: string;
31	  lane: string;
32	  reviewRunId: string;
33	  writerSessionId: string;
34	  dispatchPromptDigest: string;
35	  dispatchBindingDigest: string;
36	  hostRenderIdentityDigest: string;
37	  invocationNonce: string;
38	  issuedAt: string;
39	  expiresAt: string;
40	}
41	
42	export interface SignedNativeReviewInvocationAttestation extends NativeReviewInvocationClaims {
43	  signature: SignatureBase64;
44	}
45	
46	export type NativeReviewInvocationExpected = Omit<
47	  NativeReviewInvocationClaims,
48	  'schemaVersion' | 'brokerId' | 'adapterId' | 'invocationNonce' | 'issuedAt' | 'expiresAt'
49	>;
50	
51	export type NativeReviewInvocationVerification =
52	  | { ok: true; broker: NativeReviewBrokerRegistration; attestationDigest: string }
53	  | { ok: false; reason: string };
54	
55	function unsignedAttestation(
56	  attestation: SignedNativeReviewInvocationAttestation,
57	): NativeReviewInvocationClaims {
58	  const { signature: _signature, ...claims } = attestation;
59	  return claims;
60	}
61	
62	function nonEmpty(value: unknown): value is string {
63	  return typeof value === 'string' && value.trim().length > 0;
64	}
65	
66	function validDigest(value: unknown): value is string {
67	  return typeof value === 'string' && /^(?:sha256:)?[a-f0-9]{64}$/.test(value);
68	}
69	
70	function validClaims(claims: NativeReviewInvocationClaims): boolean {
71	  return claims.schemaVersion === NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA
72	    && /^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$/.test(claims.brokerId)
73	    && /^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$/.test(claims.adapterId)
74	    && (claims.host === 'codex' || claims.host === 'claude')
75	    && nonEmpty(claims.storyId)
76	    && nonEmpty(claims.agent)
77	    && nonEmpty(claims.lane)
78	    && nonEmpty(claims.reviewRunId)
79	    && nonEmpty(claims.writerSessionId)
80	    && validDigest(claims.dispatchPromptDigest)
81	    && validDigest(claims.dispatchBindingDigest)
82	    && validDigest(claims.hostRenderIdentityDigest)
83	    && /^[A-Za-z0-9][A-Za-z0-9._-]{15,127}$/.test(claims.invocationNonce)
84	    && Number.isFinite(Date.parse(claims.issuedAt))
85	    && Number.isFinite(Date.parse(claims.expiresAt));
86	}
87	
88	/**
89	 * Host-adapter SDK helper. Lattice exposes no CLI issuer and stores no broker
90	 * private key; only a separately registered host broker can produce a trusted
91	 * signature. Calling this helper with a self-generated key remains untrusted.
92	 */
93	export function signNativeReviewInvocationAttestation(
94	  claims: NativeReviewInvocationClaims,
95	  privateKey: PrivateKeyBase64,
96	): SignedNativeReviewInvocationAttestation {
97	  return { ...claims, signature: signCanonical(claims, privateKey) };
98	}
99	
100	export function verifyNativeReviewInvocationAttestation(args: {
101	  attestation: SignedNativeReviewInvocationAttestation;
102	  trustedBrokers: readonly NativeReviewBrokerRegistration[];
103	  expected: NativeReviewInvocationExpected;
104	  now?: number;
105	  requireFresh?: boolean;
106	}): NativeReviewInvocationVerification {
107	  const claims = unsignedAttestation(args.attestation);
108	  if (!validClaims(claims)) return { ok: false, reason: 'native invocation attestation claims are malformed' };
109	  const matchingBrokers = args.trustedBrokers.filter(candidate =>
110	    candidate.brokerId === claims.brokerId
111	    && candidate.adapterId === claims.adapterId
112	    && candidate.host === claims.host);
113	  if (matchingBrokers.length !== 1) {
114	    return { ok: false, reason: 'native invocation attestation issuer is not one uniquely registered host broker' };
115	  }
116	  const broker = matchingBrokers[0]!;
117	  if (!verifyCanonical(claims, args.attestation.signature, broker.publicKey)) {
118	    return { ok: false, reason: 'native invocation attestation signature is invalid' };
119	  }
120	  const now = args.now ?? Date.now();
121	  const issuedAt = Date.parse(claims.issuedAt);
122	  const expiresAt = Date.parse(claims.expiresAt);
123	  if (issuedAt > now + 5_000 || expiresAt <= issuedAt || expiresAt - issuedAt > 120_000
124	    || ((args.requireFresh ?? true) && expiresAt < now)) {
125	    return { ok: false, reason: 'native invocation attestation is expired or outside the bounded issuance window' };
126	  }
127	  for (const field of [
128	    'host',
129	    'storyId',
130	    'agent',
131	    'lane',
132	    'reviewRunId',
133	    'writerSessionId',
134	    'dispatchPromptDigest',
135	    'dispatchBindingDigest',
136	    'hostRenderIdentityDigest',
137	  ] as const) {
138	    if (claims[field] !== args.expected[field]) {
139	      return { ok: false, reason: `native invocation attestation ${field} does not match the exact review invocation` };
140	    }
141	  }
142	  return {
143	    ok: true,
144	    broker,
145	    attestationDigest: `sha256:${digestCanonicalJson(args.attestation)}`,
146	  };
147	}
148	
149	function consumptionPath(projectRoot: string, attestation: SignedNativeReviewInvocationAttestation): string {
150	  const canonicalRoot = resolveCanonicalRuntimeProjectRoot(projectRoot);
151	  return join(
152	    canonicalRoot,
153	    '.lattice',
154	    'runtime',
155	    'native-review-invocations',
156	    attestation.brokerId,
157	    `${attestation.invocationNonce}.json`,
158	  );
159	}
160	
161	/** Verify and atomically burn the broker nonce exactly once. */
162	export function consumeNativeReviewInvocationAttestation(args: {
163	  projectRoot: string;
164	  attestation: SignedNativeReviewInvocationAttestation;
165	  trustedBrokers: readonly NativeReviewBrokerRegistration[];
166	  expected: NativeReviewInvocationExpected;
167	  now?: number;
168	}): NativeReviewInvocationVerification {
169	  const verified = verifyNativeReviewInvocationAttestation(args);
170	  if (!verified.ok) return verified;
171	  const path = consumptionPath(args.projectRoot, args.attestation);
172	  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
173	  try {
174	    writeFileSync(path, `${JSON.stringify({
175	      schemaVersion: 'lattice.native_review_invocation_consumption.v1',
176	      brokerId: args.attestation.brokerId,
177	      invocationNonce: args.attestation.invocationNonce,
178	      attestationDigest: verified.attestationDigest,
179	      consumedAt: new Date(args.now ?? Date.now()).toISOString(),
180	    })}\n`, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
181	  } catch (error) {
182	    if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
183	      return { ok: false, reason: 'native invocation attestation nonce was already consumed' };
184	    }
185	    throw error;
186	  }
187	  return verified;
188	}
189	
190	/**
191	 * Read the capability only from a broker-supplied inherited descriptor. Inline
192	 * environment tokens are deliberately unsupported because they are forgeable
193	 * and commonly inherited by raw provider children.
194	 */
195	export function readNativeReviewInvocationAttestationFromFd(
196	  env: NodeJS.ProcessEnv = process.env,
197	): SignedNativeReviewInvocationAttestation | null {
198	  const rawFd = env.LATTICE_NATIVE_REVIEW_ATTESTATION_FD?.trim();
199	  if (!rawFd) return null;
200	  const fd = Number(rawFd);
201	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
202	    throw new Error('native invocation attestation fd must be an inherited descriptor between 3 and 255');
203	  }
204	  const raw = readFileSync(fd, 'utf8');
205	  if (Buffer.byteLength(raw, 'utf8') > 64 * 1024) {
206	    throw new Error('native invocation attestation exceeds 64 KiB');
207	  }
208	  let parsed: unknown;
209	  try {
210	    parsed = JSON.parse(raw);
211	  } catch {
212	    throw new Error('native invocation attestation fd does not contain JSON');
213	  }
214	  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
215	    throw new Error('native invocation attestation fd does not contain an object');
216	  }
217	  return parsed as SignedNativeReviewInvocationAttestation;
218	}
219	"}]},"parent_tool_use_id":"toolu_01Vnn1WZZJFZJbL41f1FUhL4","session_id":"f15e2077-72ea-410c-8904-c79687dc9acf","uuid":"f10f8b8a-51ff-488f-b650-dce3d2019aca","timestamp":"2026-08-18T08:45:26.785Z","subagent_type":"Explore","task_description":"Review managed-review-evidence modules"}

{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01Mjr25EmfcE9o3oBEdCTeKD","type":"tool_result","content":"1	import { createHash } from 'node:crypto';
2	import { execFileSync } from 'node:child_process';
