45	function providerForProcess(comm: string, command: string): PromptHost | null {
46	  const executableNames = [basename(comm), basename(command.trim().split(/\s+/, 1)[0] ?? '')]
47	    .map(value => value.toLowerCase());
48	  if (executableNames.some(value => value === 'codex' || value.startsWith('codex-'))) return 'codex';
49	  if (executableNames.some(value => value === 'claude' || value === 'claude-code' || value.startsWith('claude-'))) return 'claude';
50	  return null;
51	}
