57	/** Classify every visible provider family, retaining nearest-first order. */
58	export function classifyNativeHostProcessLineage(
59	  rows: readonly NativeHostProcessLineageRow[],
60	): NativeHostProcessObservation {
61	  const lineage = rows.map(row => ({
62	    pid: row.pid,
63	    ppid: row.ppid,
64	    comm: basename(row.comm),
65	    commandDigest: commandDigest(row.command),
66	  }));
67	  const providerFamilies: PromptHost[] = [];
68	  for (const row of rows) {
69	    const provider = providerForProcess(row.comm, row.command);
70	    if (provider && !providerFamilies.includes(provider)) providerFamilies.push(provider);
71	  }
72	  const host = providerFamilies[0];
73	  if (!host) throw new Error('native process lineage contains no Codex/Claude provider family');
74	  return {
75	    host,
76	    providerFamilies,
77	    mixedProviderFamilies: providerFamilies.length > 1,
78	    processLineageDigest: `sha256:${digestCanonicalJson({
79	      schemaVersion: 'lattice.native_review_process_lineage.v2',
80	      host,
81	      providerFamilies,
82	      lineage,
83	    })}`,
84	  };
85	}
