87	/** Inspect the complete visible Codex/Claude ancestry; inherited env is not provenance. */
88	export function observeNativeHostProcess(startPid = process.ppid): NativeHostProcessObservation | null {
89	  if (process.platform === 'win32') return null;
90	  let pid = startPid;
91	  const lineage: NativeHostProcessLineageRow[] = [];
92	  const seen = new Set<number>();
93	  let complete = false;
94	  for (let depth = 0; depth < 32 && Number.isInteger(pid) && pid > 1 && !seen.has(pid); depth += 1) {
95	    seen.add(pid);
96	    let raw: string;
97	    try {
98	      raw = execFileSync('ps', ['-o', 'ppid=', '-o', 'comm=', '-o', 'command=', '-p', String(pid)], {
99	        encoding: 'utf8',
100	        timeout: 1_000,
101	        stdio: ['ignore', 'pipe', 'ignore'],
102	      }).trim();
103	    } catch {
104	      return null;
105	    }
106	    const match = raw.match(/^\s*(\d+)\s+(\S+)\s+(.+)$/s);
107	    if (!match) return null;
108	    const ppid = Number(match[1]);
109	    const comm = match[2] ?? '';
110	    const command = match[3] ?? '';
111	    lineage.push({ pid, ppid, comm, command });
112	    const classified = lineage.some(row => providerForProcess(row.comm, row.command))
113	      ? classifyNativeHostProcessLineage(lineage)
114	      : null;
115	    if (classified?.mixedProviderFamilies) return classified;
116	    if (ppid <= 1) {
117	      complete = true;
118	      break;
119	    }
120	    pid = ppid;
121	  }
122	  return complete && lineage.some(row => providerForProcess(row.comm, row.command))
123	    ? classifyNativeHostProcessLineage(lineage)
124	    : null;
125	}
