151	  attestation?: SignedNativeReviewInvocationAttestation;
152	  trustedBrokers?: readonly NativeReviewBrokerRegistration[];
153	  observeProcess?: () => NativeHostProcessObservation | null;
154	}): NativeReviewEvidenceBinding {
155	  const nativeHost = promptHostForSession(args.identity);
156	  if (nativeHost === null || !args.identity.nativeSessionRef) {
157	    throw new Error('native reviewer authority requires a supported host-adapter identity (codex or claude-code)');
158	  }
159	  if (nativeHost !== args.dispatch.hostRenderHost) {
160	    throw new Error(
161	      `cross-provider direct reviewer evidence is advisory-only: current environment host=${nativeHost}, `
162	      + `signed dispatch host=${args.dispatch.hostRenderHost}; use cross_host_review/host_run managed reviewer evidence`,
163	    );
164	  }
165	  const attestation = args.attestation ?? readNativeReviewInvocationAttestationFromFd();
166	  if (!attestation) {
167	    throw new Error(
168	      'native reviewer authority requires a registered host-adapter invocation attestation; '
169	      + 'without an adapter broker, direct evidence is advisory-only and formal review must use managed reviewer evidence',
170	    );
171	  }
172	  const trustedBrokers = args.trustedBrokers ?? trustedNativeReviewBrokers(args.projectRoot);
173	  const verified = consumeNativeReviewInvocationAttestation({
174	    projectRoot: args.projectRoot,
175	    attestation,
176	    trustedBrokers,
177	    expected: {
178	      host: nativeHost,
179	      storyId: args.storyId,
180	      agent: args.agent,
181	      lane: args.lane,
182	      reviewRunId: args.reviewRunId,
183	      writerSessionId: args.identity.sessionId,
184	      dispatchPromptDigest: args.dispatch.dispatchPromptDigest,
185	      dispatchBindingDigest: args.dispatch.dispatchBindingDigest,
186	      hostRenderIdentityDigest: args.dispatch.hostRenderIdentityDigest,
187	    },
188	  });
189	  if (!verified.ok) {
190	    throw new Error(`native reviewer invocation attestation rejected: ${verified.reason}`);
191	  }
192	  const observedProcess = (args.observeProcess ?? observeNativeHostProcess)();
193	  if (observedProcess?.mixedProviderFamilies) {
194	    throw new Error(
195	      `cross-provider direct reviewer evidence is advisory-only: mixed provider ancestry=${(observedProcess.providerFamilies ?? []).join('->')}; `
196	      + 'use cross_host_review/host_run managed reviewer evidence',
197	    );
198	  }
199	  if (observedProcess && observedProcess.host !== nativeHost) {
200	    throw new Error(
201	      `cross-provider direct reviewer evidence is advisory-only: current environment host=${nativeHost}, `
202	      + `nearest provider process=${observedProcess.host}; use cross_host_review/host_run managed reviewer evidence`,
203	    );
204	  }
205	  return {
206	    schemaVersion: 'lattice.native_review_evidence_binding.v2',
207	    host: nativeHost,
208	    storyId: args.storyId,
209	    agent: args.agent,
210	    lane: args.lane,
211	    reviewRunId: args.reviewRunId,
212	    dispatchPromptDigest: args.dispatch.dispatchPromptDigest,
213	    dispatchBindingDigest: args.dispatch.dispatchBindingDigest,
214	    hostRenderIdentityDigest: args.dispatch.hostRenderIdentityDigest,
215	    writerSessionId: args.identity.sessionId,
216	    sessionSource: args.identity.sessionSource,
217	    brokerId: attestation.brokerId,
218	    adapterId: attestation.adapterId,
219	    invocationNonce: attestation.invocationNonce,
220	    attestationDigest: verified.attestationDigest,
221	    attestation,
222	    ...(observedProcess ? { processLineageDigest: observedProcess.processLineageDigest } : {}),
223	    ...(args.identity.nativeSessionRef ? { nativeSessionRef: args.identity.nativeSessionRef } : {}),
224	  };
225	}
